function readStore(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));if(value===null)return fallback;if(key==="yoxi.events")return Array.isArray(value)?value.filter(v=>v&&typeof v.event==="string").slice(-500):[];if(key==="yoxi.preference")return Array.isArray(value.choices)&&value.choices.length===3&&value.choices.every((v,i)=>stages[i].values.includes(v))&&(value.excludedTypes===undefined||Array.isArray(value.excludedTypes)&&value.excludedTypes.length<=9&&value.excludedTypes.every(v=>["meal","snack","coffee","park","culture","indoor","convenience","walk","toilet"].includes(v)))?value:fallback;return value;}catch{return fallback;}}
